"""Run-local stdio MCP bridge for AppWorld.

The bridge exposes a small set of structured tools on top of the persistent
AppWorld shell.  Every tool except the raw ``execute`` tool reduces a common,
error-prone Python snippet to a single validated call:

* ``appworld_execute``       arbitrary Python in the AppWorld shell
* ``appworld_call``          one ``apis.<app>.<api>(**params)`` call
* ``appworld_task``          active task + supervisor credentials in one call
* ``appworld_api_docs``      API names/descriptions or one detailed API doc
* ``appworld_answer_check``  pre-submit check of an answer's JSON type
* ``appworld_complete``      mark the active task complete (with optional answer)

The world process only accepts an ``execute`` operation, so the convenience
tools are compiled into a short code string and sent through the same
connection.  They do not bypass the world lifecycle guard or task grading.
"""
import asyncio
import json
import os
from pathlib import Path
import sys


CONNECTION_FILE = "appworld-connection.json"
READ_LIMIT = 8 * 1024 * 1024


def _find_connection_file() -> Path | None:
    candidates = [Path.cwd() / CONNECTION_FILE]
    plugin_root = os.environ.get("CLAUDE_PLUGIN_ROOT")
    if plugin_root:
        candidates.append(Path(plugin_root) / CONNECTION_FILE)
    candidates.append(Path(__file__).resolve().parent.parent / CONNECTION_FILE)
    for candidate in candidates:
        if candidate.is_file():
            return candidate
    return None


async def send_code(code: str) -> dict:
    """Execute *code* in the persistent AppWorld shell and return its JSON line."""
    connection_file = _find_connection_file()
    if connection_file is None:
        return {"error": f"AppWorld connection file {CONNECTION_FILE!r} not found in cwd or plugin root."}
    socket = json.loads(connection_file.read_text())["socket"]
    reader, writer = await asyncio.open_unix_connection(socket, limit=READ_LIMIT)
    try:
        writer.write((json.dumps({"operation": "execute", "code": code}) + "\n").encode())
        await writer.drain()
        raw = (await reader.readline()).decode().strip()
    finally:
        writer.close()
        await writer.wait_closed()

    if not raw:
        return {"error": "AppWorld shell returned an empty response."}
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        return {"output": raw}


def format_world_result(data: dict) -> str:
    """Turn a world response dict into a compact, model-friendly string."""
    if not isinstance(data, dict):
        return str(data)

    if data.get("task_terminal"):
        return "TASK TERMINAL: " + json.dumps(data, ensure_ascii=False)

    parts = []
    if data.get("error"):
        parts.append("ERROR: " + str(data["error"]))
        if data.get("error_type"):
            parts.append("ERROR TYPE: " + str(data["error_type"]))
    if data.get("output"):
        parts.append(str(data["output"]).rstrip())
    if "task_completed" in data and data["task_completed"] is not None:
        parts.append("TASK_COMPLETED: " + ("true" if data["task_completed"] else "false"))
    if not parts:
        parts.append(json.dumps(data, ensure_ascii=False))
    return "\n".join(parts)


def _json_literal(value) -> str:
    return json.dumps(value, ensure_ascii=False)


def _call_tool_code(app_name: str, api_name: str, params: dict) -> str:
    return (
        "import json\n"
        "import inspect\n"
        "import traceback\n"
        f"params = json.loads({_json_literal(json.dumps(params, ensure_ascii=False))})\n"
        f"try:\n"
        f"    app = getattr(apis, {_json_literal(app_name)})\n"
        "except Exception:\n"
        f"    app = apis[{_json_literal(app_name)}]\n"
        "try:\n"
        f"    api = getattr(app, {_json_literal(api_name)})\n"
        "except Exception:\n"
        f"    api = app[{_json_literal(api_name)}]\n"
        "try:\n"
        "    result = api(**params)\n"
        "except Exception as exc:\n"
        "    try:\n"
        "        signature = str(inspect.signature(api))\n"
        "    except Exception:\n"
        "        signature = 'unavailable'\n"
        "    try:\n"
        "        doc = apis.api_docs.show_api_doc("
        f"app_name={_json_literal(app_name)}, api_name={_json_literal(api_name)})\n"
        "        documented_parameters = doc.get('parameters') if isinstance(doc, dict) else doc\n"
        "    except Exception:\n"
        "        documented_parameters = None\n"
        "    error_type = 'TypeError' if isinstance(exc, TypeError) else type(exc).__name__\n"
        "    print(json.dumps({'error': error_type + ': ' + str(exc), "
        f"'app': {_json_literal(app_name)}, "
        f"'api': {_json_literal(api_name)}, "
        "'expected_signature': signature, "
        "'documented_parameters': documented_parameters, "
        "'traceback': traceback.format_exc(limit=3)}, "
        "ensure_ascii=False, indent=2, default=str))\n"
        "else:\n"
        "    print(json.dumps(result, ensure_ascii=False, indent=2, default=str))\n"
    )


def _task_tool_code() -> str:
    return (
        "import json\n"
        "print(json.dumps({\n"
        "    'active_task': apis.supervisor.show_active_task(),\n"
        "    'supervisor_profile': apis.supervisor.show_profile(),\n"
        "    'supervisor_addresses': apis.supervisor.show_addresses(),\n"
        "    'supervisor_payment_cards': apis.supervisor.show_payment_cards(),\n"
        "    'account_passwords': apis.supervisor.show_account_passwords(),\n"
        "}, ensure_ascii=False, indent=2, default=str))\n"
    )


def _api_docs_tool_code(app_name: str, api_name=None) -> str:
    app_json = _json_literal(app_name)
    if api_name:
        api_json = _json_literal(api_name)
        return (
            "import json\n"
            f"result = apis.api_docs.show_api_doc(app_name={app_json}, api_name={api_json})\n"
            "print(json.dumps(result, ensure_ascii=False, indent=2, default=str))\n"
        )
    return (
        "import json\n"
        f"result = apis.api_docs.show_api_descriptions(app_name={app_json})\n"
        "print(json.dumps(result, ensure_ascii=False, indent=2, default=str))\n"
    )


def _answer_check_code(answer) -> str:
    answer_json = _json_literal(answer)
    return (
        "import json\n"
        f"answer = json.loads({_json_literal(answer_json)})\n"
        "try:\n"
        "    active = apis.supervisor.show_active_task()\n"
        "except Exception as exc:\n"
        "    active = {'error': str(exc)}\n"
        "if isinstance(active, dict):\n"
        "    instruction = active.get('instruction')\n"
        "    task_type = active.get('task_type')\n"
        "    answer_type = active.get('answer_type')\n"
        "else:\n"
        "    instruction = getattr(active, 'instruction', None) or str(active)\n"
        "    task_type = getattr(active, 'task_type', None)\n"
        "    answer_type = getattr(active, 'answer_type', None)\n"
        "expected = str(answer_type).lower() if answer_type is not None else None\n"
        "actual = type(answer).__name__\n"
        "type_map = {\n"
        "    'str': 'string', 'string': 'string', 'text': 'string',\n"
        "    'int': 'integer', 'integer': 'integer',\n"
        "    'float': 'number', 'number': 'number', 'numeric': 'number',\n"
        "    'bool': 'boolean', 'boolean': 'boolean',\n"
        "    'list': 'list', 'array': 'list', 'list[str]': 'list', 'string_list': 'list',\n"
        "    'date': 'date', 'time': 'time', 'datetime': 'datetime',\n"
        "}\n"
        "want = type_map.get(expected)\n"
        "if want is not None:\n"
        "    checks = {\n"
        "        'string': isinstance(answer, str),\n"
        "        'integer': isinstance(answer, int) and not isinstance(answer, bool),\n"
        "        'number': isinstance(answer, (int, float)) and not isinstance(answer, bool),\n"
        "        'boolean': isinstance(answer, bool),\n"
        "        'list': isinstance(answer, list),\n"
        "        'date': isinstance(answer, str),\n"
        "        'time': isinstance(answer, str),\n"
        "        'datetime': isinstance(answer, str),\n"
        "    }\n"
        "    ok = checks.get(want, False)\n"
        "    if ok:\n"
        "        verdict = 'MATCH'\n"
        "    else:\n"
        "        verdict = 'MISMATCH: task wants ' + want + ', but answer is ' + actual\n"
        "elif expected is not None:\n"
        "    verdict = 'UNKNOWN_ANSWER_TYPE: ' + expected\n"
        "else:\n"
        "    verdict = ('NO_ANSWER_TYPE_ON_TASK; infer the expected JSON type from the instruction: '\n"
        "               'JSON number for numeric answers, JSON string for names/emails/dates/yes-no, '\n"
        "               'JSON list when the task asks for multiple items, or null for action tasks.')\n"
        "instruction_text = str(instruction or '').strip()\n"
        "inferred_task_type = 'question' if instruction_text.endswith('?') else 'action_or_unknown'\n"
        "if task_type is None:\n"
        "    task_type = inferred_task_type\n"
        "task_type_lower = str(task_type).lower()\n"
        "if task_type_lower in ('action', 'action_task', 'actiontask') and answer is not None:\n"
        "    verdict += '; NOTE: task_type is action, so answer should usually be omitted or null'\n"
        "if task_type_lower in ('question', 'question_task', 'questiontask') and answer is None:\n"
        "    verdict += '; NOTE: task_type is question, so answer should not be null'\n"
        "print(json.dumps({\n"
        "    'active_instruction': instruction,\n"
        "    'task_type': task_type,\n"
        "    'inferred_task_type': inferred_task_type,\n"
        "    'expected_answer_type': answer_type,\n"
        "    'provided_answer': answer,\n"
        "    'provided_json_type': actual,\n"
        "    'verdict': verdict,\n"
        "}, ensure_ascii=False, indent=2, default=str))\n"
    )


def _complete_tool_code(answer) -> str:
    answer_json = _json_literal(answer)
    return (
        "import json\n"
        f"answer = json.loads({_json_literal(answer_json)})\n"
        "result = apis.supervisor.complete_task(answer=answer)\n"
        "print(json.dumps({'complete_result': result}, "
        "ensure_ascii=False, indent=2, default=str))\n"
    )


TOOLS = [
    {
        "name": "appworld_execute",
        "description": (
            "Execute arbitrary Python code in the persistent AppWorld shell. "
            "Use this for multi-step or loop-based API work; use appworld_call "
            "for a single simple API call. The shell already exposes apis and "
            "requester, and variables persist between calls. Print results with "
            "print(json.dumps(result, indent=2)) when they are nested."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {"code": {"type": "string"}},
            "required": ["code"],
            "additionalProperties": False,
        },
    },
    {
        "name": "appworld_call",
        "description": (
            "Call one AppWorld API directly: apis.<app_name>.<api_name>(**params). "
            "Prefer appworld_execute when you need several calls, loops, or "
            "computed parameters in one interaction. If the call raises, the tool "
            "returns the API's documented parameters when available plus any "
            "Python signature/traceback for faster argument correction."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {
                "app_name": {"type": "string"},
                "api_name": {"type": "string"},
                "params": {
                    "type": "object",
                    "description": "Keyword arguments for the API, e.g. access_token and query fields.",
                },
            },
            "required": ["app_name", "api_name"],
            "additionalProperties": False,
        },
    },
    {
        "name": "appworld_task",
        "description": (
            "Read the active task and the supervisor's profile, addresses, "
            "payment cards, and app account passwords in one call. Use this at "
            "the start of every task and whenever you need credentials for an app. "
            "A prompt-time hook normally injects this same snapshot; call this "
            "tool if that snapshot is missing or stale."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {},
            "required": [],
            "additionalProperties": False,
        },
    },
    {
        "name": "appworld_api_docs",
        "description": (
            "Get AppWorld API documentation. If api_name is omitted, returns "
            "compact name+description pairs for every API in app_name. If "
            "api_name is given, returns the detailed doc (parameters and "
            "response schemas) for that one API. Use appworld_call with "
            "api_docs.search_api_docs for keyword search across apps."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {
                "app_name": {"type": "string"},
                "api_name": {"type": "string"},
            },
            "required": ["app_name"],
            "additionalProperties": False,
        },
    },
    {
        "name": "appworld_answer_check",
        "description": (
            "Check a proposed final answer before appworld_complete. If the active "
            "task exposes an answer_type, the tool compares the proposed answer's "
            "JSON type and returns MATCH/MISMATCH; otherwise it reports that no "
            "answer_type is exposed and echoes the instruction with type-inference "
            "guidance. This is advisory: it never submits or blocks completion."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {
                "answer": {
                    "type": ["string", "number", "boolean", "array", "null"],
                    "description": "Proposed answer for a question task; omit/null for action tasks.",
                },
            },
            "required": [],
            "additionalProperties": False,
        },
    },
    {
        "name": "appworld_complete",
        "description": (
            "Mark the active AppWorld task complete. Pass answer only for "
            "question tasks, as a concise JSON value such as a number, yes/no, true/false, "
            "a name/email, or a list; omit answer for action tasks. Call exactly once, "
            "after the requested state has been verified. For question tasks, call "
            "appworld_answer_check first and fix any mismatch."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {
                "answer": {
                    "type": ["string", "number", "boolean", "array", "null"],
                    "description": "Concise answer for question tasks; omit or null for action tasks.",
                },
            },
            "required": [],
            "additionalProperties": False,
        },
    },
]


def _tool_call_result(name: str, arguments: dict) -> dict:
    if name == "appworld_execute":
        code = arguments.get("code", "")
        if not isinstance(code, str) or not code.strip():
            raise ValueError("appworld_execute requires a non-empty 'code' string")
        data = asyncio.run(send_code(code))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    if name == "appworld_call":
        app_name = arguments.get("app_name")
        api_name = arguments.get("api_name")
        params = arguments.get("params", {})
        if not isinstance(app_name, str) or not app_name.strip():
            raise ValueError("appworld_call requires 'app_name'")
        if not isinstance(api_name, str) or not api_name.strip():
            raise ValueError("appworld_call requires 'api_name'")
        if not isinstance(params, dict):
            raise ValueError("appworld_call 'params' must be an object")
        data = asyncio.run(send_code(_call_tool_code(app_name, api_name, params)))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    if name == "appworld_task":
        data = asyncio.run(send_code(_task_tool_code()))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    if name == "appworld_api_docs":
        app_name = arguments.get("app_name")
        api_name = arguments.get("api_name")
        if not isinstance(app_name, str) or not app_name.strip():
            raise ValueError("appworld_api_docs requires 'app_name'")
        if api_name is not None and (not isinstance(api_name, str) or not api_name.strip()):
            raise ValueError("appworld_api_docs 'api_name' must be a non-empty string when set")
        data = asyncio.run(send_code(_api_docs_tool_code(app_name, api_name)))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    if name == "appworld_answer_check":
        answer = arguments.get("answer", None)
        data = asyncio.run(send_code(_answer_check_code(answer)))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    if name == "appworld_complete":
        answer = arguments.get("answer", None)
        data = asyncio.run(send_code(_complete_tool_code(answer)))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    raise ValueError(f"Unknown tool: {name}")


def main():
    for line in sys.stdin:
        request = json.loads(line)
        if "id" not in request:
            continue
        request_id = request["id"]
        method = request.get("method")
        try:
            if method == "initialize":
                result = {
                    "protocolVersion": request["params"]["protocolVersion"],
                    "capabilities": {"tools": {}},
                    "serverInfo": {"name": "appworld", "version": "1.2.0"},
                }
            elif method == "ping":
                result = {}
            elif method == "tools/list":
                result = {"tools": TOOLS}
            elif method == "tools/call":
                result = _tool_call_result(
                    request["params"]["name"], request["params"].get("arguments", {})
                )
            else:
                print(
                    json.dumps(
                        {
                            "jsonrpc": "2.0",
                            "id": request_id,
                            "error": {"code": -32601, "message": "Method not found"},
                        }
                    ),
                    flush=True,
                )
                continue
        except Exception as error:
            result = {
                "content": [{"type": "text", "text": str(error)}],
                "isError": True,
            }
        print(
            json.dumps({"jsonrpc": "2.0", "id": request_id, "result": result}, default=str),
            flush=True,
        )


if __name__ == "__main__":
    main()

