texts.cf8e969853373fba376e9cd01776c5b658ee0b84:
"""Run-local stdio MCP bridge for AppWorld.

This bridge keeps the small, validated tool surface of the successful simple
design, but adds two things the archive has not yet combined:

* **Read-only self-audit with no gate.**  The server records a concise,
  in-memory transcript of every world interaction (tool, app/api, params keys,
  outcome, and a short preview of the response).  ``appworld_audit`` shows the
  active instruction plus that transcript.  Unlike the failed audit-gate
  design, completion remains fail-open: the audit is purely advisory and never
  blocks ``appworld_complete``.

* **Cheaper, proactive API discovery and debugging.**  ``appworld_apps`` lists
  every available app in one call, ``appworld_search_docs`` searches API docs
  by keyword, ``appworld_inspect`` returns the exact Python signature and
  docstring for one API *without executing it*, and ``appworld_call`` now
  catches failures and attaches the callable signature, docstring, and a short
  traceback directly to the error text.  This targets wrong-app and
  wrong-argument failures while keeping every tool single-purpose and fail-open.

The world process only accepts an ``execute`` operation, so every convenience
tool is compiled into a short code string and sent through the same Unix
socket.  No tool bypasses the world lifecycle guard or task grading.
"""
import asyncio
import json
from pathlib import Path
import sys


CONNECTION_FILE = "appworld-connection.json"
READ_LIMIT = 8 * 1024 * 1024

# In-memory session state.  The MCP server lives for the whole task, so this is
# a reliable place to keep the active instruction and a compact call log.
STATE = {"active_task": None, "active_task_raw": None}
SESSION_LOG = []
MAX_LOG_ENTRIES = 40
MAX_PREVIEW = 500


def _preview(value, limit=MAX_PREVIEW):
    """Return a compact, single-line preview of an arbitrary value."""
    text = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False, default=str)
    text = " ".join(str(text).split())
    if len(text) > limit:
        return text[:limit] + " ..."
    return text


def _extract_json(text):
    """Best-effort parse of JSON printed by a world tool."""
    if not isinstance(text, str):
        return None
    stripped = text.strip()
    try:
        return json.loads(stripped)
    except Exception:
        # Some shells may wrap output with a prefix line; try the first {...}
        # or [...] block.
        start = min([i for i in (stripped.find("{"), stripped.find("[")) if i >= 0], default=-1)
        if start >= 0:
            try:
                return json.loads(stripped[start:])
            except Exception:
                return None
        return None


def _record(label, summary, code, data):
    """Append one compact entry to the in-memory session log."""
    entry = {
        "step": len(SESSION_LOG) + 1,
        "tool": label,
        "summary": summary,
    }
    if isinstance(data, dict):
        output = str(data.get("output", ""))
        error = str(data.get("error", ""))
        if error:
            entry["outcome"] = "error"
            entry["detail"] = _preview(error)
        elif output:
            combined = output
            if "Traceback" in combined or '"ERROR"' in combined or combined.lstrip().startswith("{") and '"ERROR"' in combined:
                entry["outcome"] = "error"
            else:
                entry["outcome"] = "ok"
            entry["detail"] = _preview(output)
        else:
            entry["outcome"] = "empty"
            entry["detail"] = _preview(data)
    else:
        entry["outcome"] = "unknown"
        entry["detail"] = _preview(data)
    SESSION_LOG.append(entry)
    if len(SESSION_LOG) > MAX_LOG_ENTRIES:
        del SESSION_LOG[: len(SESSION_LOG) - MAX_LOG_ENTRIES]


async def send_code(code: str, record: bool = True, label: str = "execute", summary: str = "") -> dict:
    """Execute *code* in the persistent AppWorld shell and return its JSON line."""
    socket = json.loads(Path(CONNECTION_FILE).read_text())["socket"]
    reader, writer = await asyncio.open_unix_connection(socket, limit=READ_LIMIT)
    try:
        writer.write((json.dumps({"operation": "execute", "code": code}) + "\n").encode())
        await writer.drain()
        raw = (await reader.readline()).decode().strip()
    finally:
        writer.close()
        await writer.wait_closed()

    if not raw:
        data = {"error": "AppWorld shell returned an empty response."}
    else:
        try:
            data = json.loads(raw)
        except json.JSONDecodeError:
            data = {"output": raw}

    if record:
        _record(label, summary or code.strip().splitlines()[0] if code.strip() else "", code, data)
    return data


def format_world_result(data: dict) -> str:
    """Turn a world response dict into a compact, model-friendly string."""
    if not isinstance(data, dict):
        return str(data)

    if data.get("task_terminal"):
        return "TASK TERMINAL: " + json.dumps(data, ensure_ascii=False)

    parts = []
    if data.get("error"):
        parts.append("ERROR: " + str(data["error"]))
        if data.get("error_type"):
            parts.append("ERROR TYPE: " + str(data["error_type"]))
    if data.get("output"):
        parts.append(str(data["output"]).rstrip())
    if "task_completed" in data and data["task_completed"] is not None:
        parts.append("TASK_COMPLETED: " + ("true" if data["task_completed"] else "false"))
    if not parts:
        parts.append(json.dumps(data, ensure_ascii=False))
    return "\n".join(parts)


def _json_literal(value) -> str:
    return json.dumps(value, ensure_ascii=False)


def _call_tool_code(app_name: str, api_name: str, params: dict) -> str:
    return (
        "import json, inspect, traceback\n"
        f"params = json.loads({_json_literal(json.dumps(params, ensure_ascii=False))})\n"
        f"app = {_json_literal(app_name)}\n"
        f"api = {_json_literal(api_name)}\n"
        "try:\n"
        "    try:\n"
        "        fn = apis[app][api]\n"
        "    except Exception:\n"
        "        fn = getattr(getattr(apis, app), api)\n"
        "except Exception as e2:\n"
        "    print(json.dumps({'ERROR': 'Cannot resolve API: ' + str(e2), "
        "'ERROR_TYPE': type(e2).__name__, "
        "'TRACEBACK': traceback.format_exc(limit=3)}, ensure_ascii=False, indent=2, default=str))\n"
        "else:\n"
        "    try:\n"
        "        result = fn(**params)\n"
        "        print(json.dumps(result, ensure_ascii=False, indent=2, default=str))\n"
        "    except Exception as e:\n"
        "        info = {'ERROR': str(e), 'ERROR_TYPE': type(e).__name__, "
        "'TRACEBACK': traceback.format_exc(limit=3)}\n"
        "        try:\n"
        "            info['SIGNATURE'] = str(inspect.signature(fn))\n"
        "        except Exception:\n"
        "            pass\n"
        "        try:\n"
        "            info['DOC'] = (inspect.getdoc(fn) or '')[:2500]\n"
        "        except Exception:\n"
        "            pass\n"
        "        print(json.dumps(info, ensure_ascii=False, indent=2, default=str))\n"
    )


