def _tool_call_result(name: str, arguments: dict) -> dict:
    if name == "appworld_execute":
        code = arguments.get("code", "")
        if not isinstance(code, str) or not code.strip():
            raise ValueError("appworld_execute requires a non-empty 'code' string")
        data = asyncio.run(send_code(code, label="appworld_execute"))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    if name == "appworld_call":
        app_name = arguments.get("app_name")
        api_name = arguments.get("api_name")
        params = arguments.get("params", {})
        if not isinstance(app_name, str) or not app_name.strip():
            raise ValueError("appworld_call requires 'app_name'")
        if not isinstance(api_name, str) or not api_name.strip():
            raise ValueError("appworld_call requires 'api_name'")
        if not isinstance(params, dict):
            raise ValueError("appworld_call 'params' must be an object")
        summary = f"call apis[{app_name!r}][{api_name!r}] params={sorted(params.keys())}"
        data = asyncio.run(send_code(_call_tool_code(app_name, api_name, params), label="appworld_call", summary=summary))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    if name == "appworld_task":
        data = asyncio.run(send_code(_task_tool_code(), label="appworld_task", summary="read active task and supervisor credentials"))
        payload = _extract_json(data.get("output"))
        if isinstance(payload, dict):
            STATE["active_task_raw"] = data.get("output")
            STATE["active_task"] = payload.get("active_task")
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    if name == "appworld_apps":
        data = asyncio.run(send_code(_apps_tool_code(), label="appworld_apps", summary="list available apps"))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    if name == "appworld_search_docs":
        query = arguments.get("query")
        if not isinstance(query, str) or not query.strip():
            raise ValueError("appworld_search_docs requires a non-empty 'query' string")
        data = asyncio.run(send_code(_search_docs_tool_code(query), label="appworld_search_docs", summary=f"search docs for {query!r}"))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    if name == "appworld_api_docs":
        app_name = arguments.get("app_name")
        api_name = arguments.get("api_name")
        if not isinstance(app_name, str) or not app_name.strip():
            raise ValueError("appworld_api_docs requires 'app_name'")
        if api_name is not None and (not isinstance(api_name, str) or not api_name.strip()):
            raise ValueError("appworld_api_docs 'api_name' must be a non-empty string when set")
        summary = f"docs {app_name}{'/' + api_name if api_name else ''}"
        data = asyncio.run(send_code(_api_docs_tool_code(app_name, api_name), label="appworld_api_docs", summary=summary))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    if name == "appworld_inspect":
        app_name = arguments.get("app_name")
        api_name = arguments.get("api_name")
        if not isinstance(app_name, str) or not app_name.strip():
            raise ValueError("appworld_inspect requires 'app_name'")
        if not isinstance(api_name, str) or not api_name.strip():
            raise ValueError("appworld_inspect requires 'api_name'")
        summary = f"inspect apis[{app_name!r}][{api_name!r}]"
        data = asyncio.run(send_code(_inspect_tool_code(app_name, api_name), label="appworld_inspect", summary=summary))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    if name == "appworld_audit":
        # Prefer the cached task to avoid spending one of the 30 execute calls.
        active_task = STATE.get("active_task")
        if active_task is None:
            data = asyncio.run(send_code(_active_task_code(), record=False))
            payload = _extract_json(data.get("output"))
            active_task = payload.get("active_task", payload) if isinstance(payload, dict) else data.get("output")
            if isinstance(payload, dict):
                STATE["active_task"] = active_task
                STATE["active_task_raw"] = data.get("output")
        recent = SESSION_LOG[-30:]
        ok_count = sum(1 for e in recent if e.get("outcome") == "ok")
        err_count = sum(1 for e in recent if e.get("outcome") == "error")
        result = {
            "active_task": active_task,
            "recent_interactions": recent,
            "outcome_counts": {"ok": ok_count, "error": err_count},
            "note": "Advisory only; appworld_complete remains fail-open.",
        }
        text = json.dumps(result, ensure_ascii=False, indent=2, default=str)
        return {"content": [{"type": "text", "text": text}]}

    if name == "appworld_complete":
        answer = arguments.get("answer", None)
        status = arguments.get("status", "success")
        if status not in ("success", "fail"):
            raise ValueError("appworld_complete 'status' must be 'success' or 'fail'")
        summary = f"complete answer={_preview(answer, 120)} status={status}"
        data = asyncio.run(send_code(_complete_tool_code(answer, status), label="appworld_complete", summary=summary))
        return {"content": [{"type": "text", "text": format_world_result(data)}]}

    raise ValueError(f"Unknown tool: {name}")


def main():
    for line in sys.stdin:
        request = json.loads(line)
        if "id" not in request:
            continue
        request_id = request["id"]
        method = request.get("method")
        try:
            if method == "initialize":
                result = {
                    "protocolVersion": request["params"]["protocolVersion"],
                    "capabilities": {"tools": {}},
                    "serverInfo": {"name": "appworld", "version": "1.2.0"},
                }
            elif method == "ping":
                result = {}
            elif method == "tools/list":
                result = {"tools": TOOLS}
            elif method == "tools/call":
                result = _tool_call_result(
                    request["params"]["name"], request["params"].get("arguments", {})
                )
            else:
                print(
                    json.dumps(
                        {
                            "jsonrpc": "2.0",
                            "id": request_id,
                            "error": {"code": -32601, "message": "Method not found"},
                        }
                    ),
                    flush=True,
                )
                continue
        except Exception as error:
            result = {
                "content": [{"type": "text", "text": str(error)}],
                "isError": True,
            }
        print(
            json.dumps({"jsonrpc": "2.0", "id": request_id, "result": result}, default=str),
            flush=True,
        )


if __name__ == "__main__":
    main()

