def _guard_execute_code(code: str) -> None:
    """Block the direct completion shortcut; the audited tool path is the only path."""
    if "complete_task" in code.lower():
        raise ValueError(
            "appworld_execute may not call complete_task. "
            "Use appworld_audit first, then appworld_complete."
        )


def _tool_call_result(name: str, arguments: dict) -> dict:
    if name == "appworld_execute":
        code = arguments.get("code", "")
        if not isinstance(code, str) or not code.strip():
            raise ValueError("appworld_execute requires a non-empty 'code' string")
        _guard_execute_code(code)
        data = asyncio.run(send_code(code))
        STATE["last_tool"] = name
        return _result(format_world_result(data))

    if name == "appworld_call":
        app_name = arguments.get("app_name")
        api_name = arguments.get("api_name")
        params = arguments.get("params", {})
        if not isinstance(app_name, str) or not app_name.strip():
            raise ValueError("appworld_call requires 'app_name'")
        if not isinstance(api_name, str) or not api_name.strip():
            raise ValueError("appworld_call requires 'api_name'")
        if not isinstance(params, dict):
            raise ValueError("appworld_call 'params' must be an object")
        if app_name.strip().lower() == "supervisor" and api_name.strip().lower() == "complete_task":
            raise ValueError(
                "Do not call supervisor.complete_task directly. "
                "Use appworld_audit first, then appworld_complete."
            )
        data = asyncio.run(send_code(_call_tool_code(app_name, api_name, params)))
        STATE["last_tool"] = name
        return _result(format_world_result(data))

    if name == "appworld_task":
        data = asyncio.run(send_code(_task_tool_code()))
        STATE["last_tool"] = name
        return _result(format_world_result(data))

    if name == "appworld_apps":
        data = asyncio.run(send_code(_apps_tool_code()))
        STATE["last_tool"] = name
        return _result(format_world_result(data))

    if name == "appworld_api_docs":
        app_name = arguments.get("app_name")
        api_name = arguments.get("api_name")
        if not isinstance(app_name, str) or not app_name.strip():
            raise ValueError("appworld_api_docs requires 'app_name'")
        if api_name is not None and (not isinstance(api_name, str) or not api_name.strip()):
            raise ValueError("appworld_api_docs 'api_name' must be a non-empty string when set")
        data = asyncio.run(send_code(_api_docs_tool_code(app_name, api_name)))
        STATE["last_tool"] = name
        return _result(format_world_result(data))

    if name == "appworld_search_docs":
        query = arguments.get("query")
        if not isinstance(query, str) or not query.strip():
            raise ValueError("appworld_search_docs requires a non-empty 'query' string")
        page_index = arguments.get("page_index", 0)
        page_limit = arguments.get("page_limit", 10)
        if type(page_index) is not int or page_index < 0:
            raise ValueError("appworld_search_docs 'page_index' must be a non-negative integer")
        if type(page_limit) is not int or not (1 <= page_limit <= 20):
            raise ValueError("appworld_search_docs 'page_limit' must be an integer between 1 and 20")
        data = asyncio.run(send_code(_search_docs_tool_code(query, page_index, page_limit)))
        STATE["last_tool"] = name
        return _result(format_world_result(data))

    if name == "appworld_audit":
        data = asyncio.run(send_code(_audit_tool_code()))
        # The gate must only unlock after a successful audit.  If the audit
        # cell raised, the agent has not actually compared the instruction with
        # a valid call log, so keep complete locked until it retries.
        STATE["last_tool"] = name if not (isinstance(data, dict) and data.get("error")) else None
        return _result(format_world_result(data))

    if name == "appworld_complete":
        answer = arguments.get("answer", None)
        if isinstance(answer, bool):
            raise ValueError(
                "appworld_complete does not accept JSON booleans. "
                "For yes/no or true/false questions pass the string "
                "\"yes\", \"no\", \"true\", or \"false\" instead."
            )
        if isinstance(answer, (list, dict)):
            raise ValueError(
                "appworld_complete does not accept lists or objects. "
                "Pass a single string or number (or null for action tasks)."
            )
        if answer is not None and not isinstance(answer, (str, int, float)):
            raise ValueError(
                "appworld_complete 'answer' must be a string, number, or null."
            )
        if STATE.get("completed"):
            raise ValueError("appworld_complete was already called; do not call it again.")
        if STATE.get("last_tool") != "appworld_audit":
            raise ValueError(
                "appworld_complete is locked until the immediately preceding "
                "successful tool is appworld_audit. Call appworld_audit, verify "
                "every instruction clause against the API call log, then retry "
                "appworld_complete."
            )
        data = asyncio.run(send_code(_complete_tool_code(answer)))
        output = str(data.get("output", "")) if isinstance(data, dict) else str(data)
        failed = bool(data.get("error")) if isinstance(data, dict) else False
        if isinstance(data, dict) and "task_completed" in data:
            failed = failed or data.get("task_completed") is False
        failed = failed or ("Execution failed" in output) or ("Traceback" in output)
        if not failed:
            STATE["completed"] = True
            STATE["last_tool"] = name
        else:
            # A complete attempt that reached the world and failed leaves the
            # task state uncertain.  Require a fresh audit before retrying.
            STATE["last_tool"] = None
        return _result(format_world_result(data))

    raise ValueError(f"Unknown tool: {name}")


def main():
    for line in sys.stdin:
        request = json.loads(line)
        if "id" not in request:
            continue
        request_id = request["id"]
        method = request.get("method")
        try:
            if method == "initialize":
                result = {
                    "protocolVersion": request["params"]["protocolVersion"],
                    "capabilities": {"tools": {}},
                    "serverInfo": {"name": "appworld", "version": "1.2.0"},
                }
            elif method == "ping":
                result = {}
            elif method == "tools/list":
                result = {"tools": TOOLS}
            elif method == "tools/call":
                result = _tool_call_result(
                    request["params"]["name"], request["params"].get("arguments", {})
                )
            else:
                print(
                    json.dumps(
                        {
                            "jsonrpc": "2.0",
                            "id": request_id,
                            "error": {"code": -32601, "message": "Method not found"},
                        }
                    ),
                    flush=True,
                )
                continue
        except Exception as error:
            result = {
                "content": [{"type": "text", "text": str(error)}],
                "isError": True,
            }
        print(
            json.dumps({"jsonrpc": "2.0", "id": request_id, "result": result}, default=str),
            flush=True,
        )


if __name__ == "__main__":
    main()
